const plans={whitebeard:'先用J短起手，K震击打飞后再选择追击或撤开。180像素外L切换消耗26能量的破空震波，兼顾牵制与击飞；I仍是170像素近距高风险连震，等对方挥空收招或落地再用，后撤后不要隔空空放。',kaido:'J试探，K突进击飞，L热息控制中距。I需要33帧准备，避免在对方空闲贴身时蓄力；观察收招后再压近，极限之后留意5秒虚弱。',akainu:'K突进抢位，L岩浆团牵制并短暂元素化。I先标记区域，消耗75能量且前摇0.90秒；先拉开距离或惩罚长收招，再让岩浆封住落点。',kizaru:'依靠快移速与J起手抢位，L有限距离闪身踢。I远距勾玉需0.90秒准备；后撤、侧换位与见闻可争取时间，但不会免除打断。',kuzan:'K冰矛与L冻结区域改变进场路径。命中减速后撤开蓄力I，离开冰面可解除压制；不要在贴身无硬直对手面前直接开大。',zoro:'近身用K鹰波接招；170像素外K切换飞斩。先后撤再放弧形剑气，命中击飞后判断是否追击。',brook:'近身K冷气剑，160像素外K飞斩。利用减速留出后撤空间，避免和重装角色连续换血。',shanks:'近距K不耗能；220像素外切换远距弧斩，消耗10能量并共享冷却。命中后选择追击或积攒霸气，L架势抵抗近身起手。',mihawk:'L弧月剑气射程长，消耗22能量。用距离迫使对手接近，避免连续挥空长前摇招式。',shiryu:'K远距刀气牵制；L透明穿身只用于走位。等现身破绽结束再按攻击，隐身不能输出。',crocodile:'先用J或沙刃确认近身，K命中后收招更快；L沙化争取调整距离，随后用预警区域压制。',marco:'L青炎再生需安全时间，受击会终止。用后撤争取恢复空档，K飞翼命中后拉开距离，必杀青焰用于连续击退。',robin:'K关节技短硬直与减速，命中后后撤准备多臂区域；勿在对手贴身时连续蓄力。',jinbe:'K水压正拳击飞后可后撤或追击；保持中距离，让对方冲进拳压范围。',franky:'K火焰喷射把对手推开，后撤后蓄力光束；机械护盾仍需资源，不要长期原地换血。'};
for(const c of roster)c.playGuide=plans[c.id]||('以「'+c.skills[0].name+'」确认距离，命中后在收招阶段接「'+c.skills[1].name+'」。'+(c.skills[2].heal||c.skills[2].regen?'后撤到安全距离再使用恢复技能。':c.skills[2].kind==='zone'?'特殊技锁定区域，用移动诱导对手进入预警落点。':c.skills[2].kind==='evade'||c.skills[2].elementalFrames?'保留特殊技资源用于规避，结束后及时离开对手射程。':c.skills[2].kind==='swap'?'空间交换需双方落地且未被防御抵抗，先逼对手出招再换位。':'根据特殊技的前摇与射程选择安全起手，保留反制能量。'));
